    return (
        <>
            <div className="flex aspect-square size-8 items-center justify-center bg-primary text-primary-foreground text-lg font-bold">
                N
            </div>
            <div className="ml-1 grid flex-1 text-left text-sm">
                <span className="mb-0.5 truncate leading-tight font-bold">
                    NekazarIA
                </span>
            </div>
        </>
    );
}
